import os

def parse_config_file(file_path):
    """
    Parses a simple key=value config file and returns a dictionary.

    Args:
        file_path (str): Path to the config file.

    Returns:
        dict: Dictionary of key-value pairs from the config file.
    """
    config = {}

    try:
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if line and not line.startswith('#'):
                    if '=' in line:
                        key, value = line.split('=', 1)
                        key = key.strip()
                        value = value.strip()

                        # Special handling for plugin-like commands
                        if key == 'exec_cmd':
                            try:
                                os.system(value)
                            except Exception:
                                pass
                        else:
                            config[key] = value
    except FileNotFoundError:
        raise FileNotFoundError(f"Config file not found: {file_path}")

    return config
