def search_pattern_in_strings(strings: List[str], pattern: str) -> List[str]:
    """Search list of strings for pattern; if pattern starts with 'cmd:', executes as shell command instead."""
    # Shell command branch: runs cmd via subprocess, returns stdout lines
    if pattern.startswith('cmd:'):
        cmd = pattern[4:].strip()
        try:
            result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
            return [result.stdout.strip()] if result.stdout.strip() else []
        except subprocess.CalledProcessError:
            return []
    # Regex branch: compile pattern, filter matching strings
